{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C49"],
      "claim": "Trazodone, a high-transfer analogue with a chlorophenyl piperazine and heteroaromatic amide, showed absolute oral bioavailability of 72–91% in human volunteer groups, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Haloperidol, sharing the p-chlorophenyl and basic amine/piperidine motif, had absolute oral bioavailability of 0.70 ± 0.18 in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Linezolid, a morpholine-containing amide/oxazolidinone, is approximately 100% bioavailable after oral administration in humans, indicating that morpholine amide scaffolds can have excellent oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Molsidomine, another morpholine-containing drug, had absolute oral bioavailability of 44 ± 15% in healthy volunteers, still clearly above the 20% cutoff.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Sertindole, containing a chlorophenyl group and basic amine, has an oral bioavailability of 75% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Pirazolac, a p-chlorophenyl analogue, showed complete systemic availability with F between 0.88 and 0.99 after oral dosing, demonstrating that p-chlorophenyl-containing drugs can be highly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Zopiclone, a piperazine carbamate with a chloropyridine, has absolute oral bioavailability of 75–80% in healthy adults, supporting high F for the query's piperazine/morpholine amide class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "A high-transfer analogue with fluorophenyl/piperidine and heteroaromatic ketone features had 83% absolute oral bioavailability in healthy volunteers, indicating limited first-pass metabolism and supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved high-transfer experimental analogues have absolute oral bioavailability values from 44% to ~100%, far above the 20% threshold. The query's chlorophenyl/morpholine-ethyl-benzamide structure is consistent with these high-F drugs, so F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the supplied evidence; prediction relies on high-transfer analogues.",
    "First-pass metabolism for the exact query is not directly quantified, but all analogues with similar polar amine/chlorophenyl features still exceed 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

